files.content:
:root {
  --bg: #1a1c2c;
  --card: #2e3350;
  --accent: #ffcd75;
  --text: #f4f4f4;
  --btn: #5a6988;
  --btn-hover: #7a8ab0;
  --btn-active: #3e4a6b;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
  image-rendering: pixelated;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 24px;
  color: var(--accent);
}

#count {
  display: block;
  font-size: 4rem;
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 32px;
  color: var(--accent);
  text-shadow: 3px 3px 0 rgba(0, 0, 0, 0.5);
  font-variant-numeric: tabular-nums;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 20px;
  min-width: 72px;
  border: 3px solid var(--accent);
  border-radius: 0;
  background: var(--btn);
  color: var(--text);
  cursor: pointer;
  transition: background 0.1s, transform 0.05s;
  image-rendering: pixelated;
  box-shadow: 3px 3px 0 rgba(0, 0, 0, 0.4);
}

button:hover {
  background: var(--btn-hover);
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

button:active {
  background: var(--btn-active);
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 rgba(0, 0, 0, 0.4);
}

.hint {
  margin-top: 24px;
  font-size: 0.875rem;
  opacity: 0.7;
  line-height: 1.4;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  #count {
    font-size: 3rem;
  }
  button {
    padding: 10px 14px;
    min-width: 60px;
  }
}

const countEl = document.getElementById('count');
let count = 0;

function render() {
  countEl.textContent = count;
}

function increase() {
  count += 1;
  render();
}

function decrease() {
  count -= 1;
  render();
}

function reset() {
  count = 0;
  render();
}

document.getElementById('increase').addEventListener('click', increase);
document.getElementById('decrease').addEventListener('click', decrease);
document.getElementById('reset').addEventListener('click', reset);

render();
